//! ♻️ Real retained history and independent miniz output distinguish effects, denied close and cached completion.
use super::*;
#[test]fn retained_inflater_close_reports_exact_independent_cpu_without_header_copy(){let _gate=gate();let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let payload:Vec<u8>=serde_json::from_value(law["payload"].clone()).unwrap();for malformed in [false,true]{let compressed=if malformed{serde_json::from_value::<Vec<u8>>(law["malformed"].clone()).unwrap()}else{miniz_oxide::deflate::compress_to_vec(&payload,6)};let mut inflater=Inflater::try_new_retained(law["historyBytes"].as_u64().unwrap()as usize,law["allocationBytes"].as_u64().unwrap()as usize).unwrap();let allocation=law["allocationBytes"].as_u64().unwrap()as usize;let(result,created,released)=observe_backing(||inflater.reserve_retained_history(allocation));assert_eq!(result.unwrap().allocated_bytes,allocation);assert_eq!((created,released),(allocation,0));let pointer=inflater.retained_history_ptr();let mut output=Vec::new();let mut at=0;let mut pending=None;let mut failure=None;for _ in 0..100000{if pending.is_none()&&at<compressed.len(){pending=Some(compressed[at]);at+=1;}match inflater.advance(&mut pending,at==compressed.len()){Ok(InflateOutcome::Wrote(byte))=>output.push(byte),Ok(InflateOutcome::NeedInput)=>assert!(at<compressed.len()),Ok(InflateOutcome::Done)=>break,Err(error)=>{failure=Some(error);break;}}}if malformed{assert_eq!(failure,Some(DeflateError::BadBlockType));assert!(miniz_oxide::inflate::decompress_to_vec(&compressed).is_err());}else{assert_eq!(failure,None);assert_eq!(output,payload);assert_eq!(miniz_oxide::inflate::decompress_to_vec(&compressed).unwrap(),payload);}let(mut items,mut bytes,mut cpu)=(law["logicalStock"].as_u64().unwrap()as usize,law["releaseStock"].as_u64().unwrap()as usize,0u64);for(index,grant)in law["grants"].as_array().unwrap().iter().enumerate(){let maximum_items=grant[0].as_u64().unwrap()as usize;let maximum_bytes=grant[1].as_u64().unwrap()as usize;assert!(maximum_items<=items&&maximum_bytes<=bytes);let(step,allocated,released)=observe_backing(||inflater.close_retained_step(maximum_items,maximum_bytes));let work=inflater.last_retained_close_work();assert_eq!(work,law["expectedCpu"][index].as_u64().unwrap());assert_eq!(allocated,0);cpu+=work;assert!(cpu<=law["fuel"].as_u64().unwrap());let released_items=match step{RetainedInflateCloseStep::Pending{released_items,released_bytes}=>{assert_eq!(released,released_bytes);bytes-=released_bytes;released_items},RetainedInflateCloseStep::Complete=>{assert_eq!(released,0);0}};items-=released_items;if index<4{assert_eq!(inflater.retained_history_ptr(),pointer);}if work==0{assert_eq!(released_items,0);assert_eq!(released,0);}}assert_eq!(cpu,law["fuel"].as_u64().unwrap());assert_eq!((items,bytes),(0,0));assert!(inflater.retained_terminal_is_empty());let((),allocated,released)=observe_backing(||drop(inflater));assert_eq!((allocated,released),(0,0));}}
